_builder_version=\"4.16\" global_colors_info=\"{}\"][et_pb_text _builder_version=\"4.16\" text_font=\"||||||||\" text_text_color=\"#ffffff\" text_letter_spacing=\"2px\" header_font=\"|||on|||||\" header_text_align=\"center\" header_letter_spacing=\"4px\" header_3_font=\"|300||on|||||\" header_3_letter_spacing=\"4px\" header_4_font=\"|||on|||||\" header_4_text_color=\"#F86E01\" header_5_font=\"||||||||\" text_orientation=\"center\" text_text_align=\"center\" global_colors_info=\"{}\"]<h4>A. Harian</h4>[/et_pb_text][et_pb_text module_class=\"small-table\" _builder_version=\"4.24.2\" hover_enabled=\"0\" global_colors_info=\"{}\" sticky_enabled=\"0\"]<div class=\"table-responsive\">\n<p>&nbsp;</p>\n<table>\n<thead>\n<tr>\n<th>No</th>\n<th>Waktu</th>\n<th>Kegiatan</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>03.30 - 04.00</td>\n<td>Sholat tahajud</td>\n</tr>\n<tr>\n<td>2</td>\n<td>04.00 - 04.45</td>\n<td>Sholat subuh dan wirid</td>\n</tr>\n<tr>\n<td>3</td>\n<td>04.45 - 05.00</td>\n<td>Wirid Ma\'tsurot(Dzikir pagi)</td>\n</tr>\n<tr>\n<td>4</td>\n<td>05.00 - 06.30</td>\n<td>Setoran Tahfidzul Qur\'an ziyadah (Setoran menambah hafalan)</td>\n</tr>\n<tr>\n<td>5</td>\n<td>06.30 - 07.30</td>\n<td>Kebersihan (piket) /MCK dan makan (sarapan pagi)</td>\n</tr>\n<tr>\n<td>6</td>\n<td>07.30 - 07.45</td>\n<td>Pemberian mufrodat bahasa arab dan inggris</td>\n</tr>\n<tr>\n<td>7</td>\n<td>07.45 - 11.50</td>\n<td>KBM Formal</td>\n</tr>\n<tr>\n<td>8</td>\n<td>11.50 - 12.10</td>\n<td>Sholat Dzuhur</td>\n</tr>\n<tr>\n<td>9</td>\n<td>12.10 - 13.00</td>\n<td>Makan siang</td>\n</tr>\n<tr>\n<td>10</td>\n<td>13.00 - 14.00</td>\n<td>Tahfidz siang</td>\n</tr>\n<tr>\n<td>11</td>\n<td>14.00 - 15.00</td>\n<td>Istirahat / tidur siang</td>\n</tr>\n<tr>\n<td>12</td>\n<td>15.00 - 15.30</td>\n<td>sholat asar dan wirid</td>\n</tr>\n<tr>\n<td>13</td>\n<td>15.30 - 15.45</td>\n<td>wirid ma\'tsurot (wirid sore)</td>\n</tr>\n<tr>\n<td>14</td>\n<td>15.45 - 17.00</td>\n<td>Setoran tahfidz Muroja\'ah (meng