ing=\"||0px|||\" custom_css_main_element=\"border-bottom: 1px solid #DDDDDD;\"][et_pb_row custom_padding=\"90px||\" _builder_version=\"3.25.4\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\" text_font=\"||||||||\" text_text_align=\"center\" header_font=\"|300||on|||||\" header_text_align=\"center\" header_letter_spacing=\"4px\"]<h1>Informasi</h1>\n<p>Dapatkan informasi menarik tentang Islam yang tentunya sangat bermanfaat untuk Anda.</p>[/et_pb_text][et_pb_blog fullwidth=\"off\" posts_number=\"3\" include_categories=\"all\" use_manual_excerpt=\"off\" show_more=\"on\" show_author=\"off\" show_date=\"off\" show_categories=\"off\" show_pagination=\"off\" module_class=\"custom-blog-grid\" _builder_version=\"3.25.4\" body_font=\"||||||||\" body_text_align=\"left\"][/et_pb_blog][/et_pb_column][/et_pb_row][/et_pb_section]', 'Beranda', '', 'inherit', 'closed', 'closed', '', '8-revision-v1', '', '', '2019-07-08 08:15:38', '2019-07-08 08:15:38', '', 8, 'https://pondokroja.com/8-revision-v1/', 0, 'revision', '', 0),
