n}\r\n.custom-blog-grid .et_pb_image_container img {\r\n	border-radius: 10px;\r\n}\r\n.custom-blog-grid .et_pb_blog_grid h2 {\r\n    font-size: 16px;\r\n    text-transform: uppercase;\r\n    letter-spacing: 2px;\r\n	font-weight: 500;\r\n}\r\n.custom-blog-grid article:hover h2.entry-title {\r\n	color: #FF147B;\r\n}\r\n.custom-blog-grid .more-link {\r\n	text-transform: capitalize;\r\n}\r\n.custom-blog-grid:after {\r\n	position: absolute;\r\n	left: 0;\r\n	right: 0;\r\n	bottom: -41px;\r\n	margin: 0 auto;\r\n	content: \'\';\r\n	width: 118px;\r\n	height: 29px;\r\n	background-image: url(\'https://pondokroja.com/wp-content/uploads/2019/07/Group-2.png\');\r\n	background-size: cover;\r\n	background-repeat: no-repeat;\r\n}\r\n.blurb-full-width .et_pb_blurb_content {\r\n	max-width: 100%;\r\n}\r\n.et-pb-controllers a {\r\n    width: 16px;\r\n    height: 16px;\r\n    border-radius: 3px;\r\n    background: transparent;\r\n	border: 1px solid #FFFFFF;\r\n}\r\n.et-pb-controllers a.et-pb-active-control {\r\n	background-color: #7BD826;\r\n	border: 1px solid #7BD826;\r\n}\r\n.et_pb_slider:hover .et-pb-arrow-prev,\r\n.et_pb_slider:hover .et-pb-arrow-next {\r\n    border: none;\r\n	background-color: #FF147B;\r\n    color: #FFFFFF!important;\r\n	border-radius: 5px;\r\n}\r\n.et_pb_slider:hover .et-pb-arrow-prev,\r\n.et_pb_slider:hover .et-pb-arrow-next {\r\n    border: none;\r\n    color: #FFFFFF!important;\r\n    border-radius: 5px;\r\n}\r\n.small-table tr td {\r\n	padding-top: 0;\r\n	padding-bottom: 0;\r\n}\r\n.small-table, \r\n.small-table table,\r\n.small-table tbody {\r\n	border: none !important;\r\n}\r\n.small-table tr th {\r\n	text-transform: uppercase;\r\n	font-size: 16px;\r\n	font-weight: 600;\r\n	letter-spacing: 2px;\r\n}\r\n.custom-testimonial .et_pb_testimonial_description_inner p:not(.et_pb_testimonial_meta) {\r\n	font-family: \'EB Garamond\',Georgia,\"Times New Roman\",serif;\r\n	font-style: italic;\r\n	letter-spacing: 0;\r\n}\r\n@media (max-width: 980px) {\r\n	.et_pb_column .et_pb_module {\r\n		padding: 0 !important;\r\n	}\r\n}\r\n.table-responsive table {\r\n	min-width: 800px;\r\n}\r\n.table-responsive {\r\n	overflow-x: auto;\r\n}\r\n@media only screen and (min-width: 981px) {\r\n	#top-menu-nav ul#top-menu li.nav-donation a {\r\n		color: #FFFFFF !important;\r\n	}\r\n}\r\n@media only screen and (min-width: 1350px) {\r\n	.single.single-post article .et_pb_section {\r\n		padding: 0;\r\n	}\r\n}\r\n.single.single-post article {\r\n	padding-bottom: 0 !important;\r\n}\r\n.single.single-post article #commentform {\r\n	padding-bottom: 0;\r\n	margin-bottom: 0;\r\n}\r\n.single.single-post article #comment-wrap {\r\n    padding-top: 30px;\r\n}\r\n.single.single-post article .et_post_meta_wrapper img {\r\n	border-radius: 20px;\r\n}\r\n.et_pb_scroll_top.et-pb-icon {\r\n    border-radius: 50px;\r\n    right: 10px;\r\n    background-color: #FF147B;\r\n    box-shadow: 0 10px 30px rgba(51,73,90,.38);\r\n    -moz-box-shadow: 0 10px 30px rgba(51,73,90,.38);\r\n    -webkit-box-shadow: 0 10px 30px rgba(51,73,90,.38);\r\n}\r\n@media only screen and (max-width: 981px) {\r\n	#fix-program .et_pb_blurb_content {\r\n		padding-top: 110px;\r\n	}\r\n	#fix-program.fix-program-ext .et_pb_blurb_content {\r\n		padding-top: 90px;\r\n	}\r\n	#fix-program .et_pb_module_header {\r\n		right: 20px;\r\n		left: 20px;\r\n		letter-spacing: 3px;\r\n	}\r\n}\r\n.winner-text strong {\r\n	font-weight: 600;\r\n}', 'Divi', '', 'inherit', 'closed', 'closed', '', '47-revision-v1', '', '', '2019-07-10 03:58:38', '2019-07-10 03:58:38', '', 47, 'https://pondokroja.com/47-revision-v1/', 0, 'revision', '', 0),
(819, 1, '2019-07-10 03:52:51', '2019-07-10 03:52:51', '[et_pb_section fb_built=\"1\" fullwidth=\"on\" _builder_version=\"3.25.4\" background_color=\"#F86E01\" custom_padding=\"0px||0px\" bottom_divider_style=\"ramp2\" bottom_divider_color=\"#F7F9FB\" bottom_divider_height=\"148px\" bottom_divider_flip=\"horizontal\"][et_pb_fullwidth_header title=\"Profil Kami\" _builder_version=\"3.25.4\" title_font=\"||||||||\" title_font_size=\"40px\" background_color=\"#F86E01\" custom_padding=\"32px||29px|||\"][/et_pb_fullwidth_header][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"3.25.4\" use_background_color_gradient=\"on\" background_color_gradient_start=\"#F7F9FB\" background_color_gradient_end=\"#e1eafb\" background_image=\"https://pondokroja.com/wp-content/uploads/2019/07/Bg.png\" background_size=\"contain\" background_position=\"bottom_center\" custom_padding=\"||120px|||\" custom_padding_tablet=\"||90px\" custom_padding_phone=\"||80px|\"][et_pb_row custom_padding=\"0px|||||\" _builder_version=\"3.25.4\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\" text_font=\"||||||||\" text_text_align=\"center\" text_text_color=\"#ffffff\" header_font=\"|||on|||||\" header_text_align=\"center\" header_letter_spacing=\"4px\" header_3_font=\"|300||on|||||\" header_3_letter_spacing=\"4px\" custom_margin=\"||10px\"]<h3>Pondok Pesantren</h3>\n<h1>Rooihatul Jannah Hidayatullah</h1>[/et_pb_text][et_pb_text _builder_version=\"3.25.4\" custom_margin=\"||72px\"]<p style=\"text-align: justify;\">Pesantren Tahfidz Putri Rooihatul Jannah (Pondok Roja) adalah lembaga pendidikan islam setingkat SMP - SMA yang menerapkan kurikulum integral pendidikan Tauhid &amp; Pendidikan Nasional dengan lebih menguatkan menghafal Al Qur\'an sebagai program unggulan sehingga mencetak kader muslimah yang berakhlakul karimah dan berwawasan luas. Dengan didukung tenaga pengajar yang berkompeten lulusan dari pesantren dan perguruan tinggi.</p>[/et_pb_text][et_pb_blurb title=\"VISI\" module_class=\"blurb-full-width\" _builder_version=\"3.25.4\" custom_margin=\"||5px\" custom_css_blurb_title=\"background: #FF147B;||color: #FFFFFF;||font-weight: 300;||text-transform: uppercase;||letter-spacing: 4px;||margin-bottom: 0;||padding: 15px 40px 15px 40px;||border-top-left-radius: 20px;||border-bottom-right-radius: 20px;||position: absolute;||left: 40px;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);||top: -27.5px;\" custom_css_blurb_content=\"padding: 50px 40px 70px 40px;||border-radius: 20px 5px 20px 5px;||background-color: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);\"]Lembaga Pendidikan Islam Pencetak Kader Pemimpin Umat yang berakhlaq mulia, berwawasan luas, dan mampu mengembangkan diri untuk tegaknya peradapan Islam.[/et_pb_blurb][et_pb_blurb title=\"Misi\" module_class=\"blurb-full-width\" _builder_version=\"3.25.4\" custom_css_blurb_title=\"background: #FF147B;||color: #FFFFFF;||font-weight: 300;||text-transform: uppercase;||letter-spacing: 4px;||margin-bottom: 0;||padding: 15px 40px 15px 40px;||border-top-left-radius: 20px;||border-bottom-right-radius: 20px;||position: absolute;||left: 40px;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);||top: -27.5px;\" custom_css_blurb_content=\"padding: 60px 40px 40px 40px;||border-radius: 20px 5px 20px 5px;||background-color: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);\"]<table class=\"table-list\" style=\"margin-bottom: 0;\">\n<tbody>\n<tr>\n<td>1.</td>\n<td></td>\n<td>Membentuk generasi muslim yang unggul, berdikari, berpengetahuan luas siap menjadi da\'i dan ulama yang intelek.</td>\n<td></td>\n</tr>\n<tr>\n<td>2.</td>\n<td></td>\n<td>Membentuk karakter atau pribadi muslim yang bertauhid, beriman dan menjalankan syariah Allah.</td>\n<td></td>\n</tr>\n<tr>\n<td>3.</td>\n<td></td>\n<td>Menjadikan kampus pesantren Rooihatul Jannah sebagai lembaga berkualitas yang representatif, eksekutif &amp; kreatif serta menjadi rujukan ummat.</td>\n<td></td>\n</tr>\n</tbody>\n</table>[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" _builder_version=\"3.25.4\" background_color=\"rgba(255,255,255,0)\" custom_padding=\"0px||60px|||\"][et_pb_row custom_padding=\"0px||0px|||\" custom_margin=\"-20px||\" _builder_version=\"3.25.4\" custom_margin_tablet=\"0px||\" custom_margin_phone=\"10px|||\" custom_margin_last_edited=\"on|phone\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\" text_font=\"||||||||\" text_text_align=\"center\" header_font=\"||||||||\" header_5_font=\"|700||on|||||\" header_5_letter_spacing=\"4px\" custom_margin=\"||10px|\"]<h5>Sejarah Singkat Berdirinya</h5>[/et_pb_text][et_pb_text _builder_version=\"3.25.4\"]<p style=\"text-align: justify;\">Tepat bulan Juli tahun 2010, empat santri Hidayatullah Surakarta mendapat tugas dari Pimpinan Hidayatullah Surakarta untuk merintis di kota Sukoharjo atau terkenal dengan sebutan kota Makmur. Mereka bernama Sigit yang berasal dari Lampung, Syarif dari Magelang, Arifin dari Solo dan Syofyan dari Ternatai. Disebuah rumah dan tanah wakaf yang beralamat dibrumbung 03/02 dukuh sukoharjo dengan lauas tanah +- 1800 m2.</p>[/et_pb_text][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"1_5,1_5,1_5,1_5,1_5\" use_custom_gutter=\"on\" gutter_width=\"1\" custom_margin=\"50px||60px\" _builder_version=\"3.25.4\" width=\"90%\" width_last_edited=\"on|phone\" animation_direction=\"bottom\" custom_css_main_element=\"background-color: #ffffff;||border-radius: 15px 15px 15px 15px;||overflow: hidden;||border-top-width: 18px;||border-color: #3c39e6;||max-width: 1440px;||box-shadow: 0px 39px 80px -6px rgba(0,0,0,0.1);||padding: 60px 40px 10px;||border-bottom: 10px solid #7CDA24;\"][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Pembina\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Suparmana HS\nProf.dr.Dr. Harijono S.pKK[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Pengawas\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Ridho\nUst. Sulaiman Rodhi[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Ketua\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Ahmad Khamim\n-[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Sekretaris\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Surya Aditya Setyawan S.Pd.I[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Bendahara\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Sumardi\n-[/et_pb_blurb][/et_pb_column][/et_pb_row][et_pb_row custom_padding=\"0px||0px|||\" _builder_version=\"3.25.4\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\"]<p style=\"text-align: justify;\">Pondok Pesantren Rooihatul Jannah Hidayatullah Sukoharjo atau lebih dikenal dengan sebutan PONDOK ROJA adalah lembaga pendidikan Islam yang berciri khas dengan sistem pendidikan modern berjenjang 6 tahun plus 1 tahun pengabdian.</p>\n<p style=\"text-align: justify;\">Program utama adalah pendidikan guru penghafal al Qur’an/ Tarbiyatul Muhafidzotil Qur’an (TMQ). Secara realitas memang pondok pesantren ini di bawah naungan yayasan Hidayatullah Sukoharjo dan merupakan bagian dari Ormas besar Hidayatullah yang berpusat di Jakarta dengan kampus induk Pesantren Hidayatullah di Gunung Tembak, Balikpapan, Kalimantan Timur. Meski begitu dari sejak awal berdirinya, para pendiri pesantren (Father Founding) selalu mengingatkan dan mewaspadai akan adanya fantisme golongan tertentu, dengan berbagai cara sehingga siapa saja dan masyarakat secara umumpun bisa ikut bergabung dalam mengembangkan dan meningkatkan mutu dan kwalitas pendidikan yang ada dalam pesantren ini.</p>\n<p style=\"text-align: justify;\">Adapun untuk mewujudkan itu semua maka subtansi ajaran Islam yang menjadi basic sistem pendidikan dan pengajaran Islam di Pondok Roja senantisa bertumpu pada Al-Qur’an dan As-Sunnah yang sesuai dengan pemahaman Salafush Sholih secara Kaffah (universal), Syumul (Komperhenshif) dan Mutakaamil (integratif). Dengan cara pandang yang seperti inilah diharapkan para Pendiri Pondok ROJA Hidayatullah Sukoharjo ini bisa menjadi Generasi yang kritis dan taktis serta tidak mudah terjebak dalam sikap-sikap fanatisme golongan (sekte / madzhab) dan sikap taklid buta (mengikuti tanpa tahu dalilnya).</p>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" _builder_version=\"3.25.4\" background_color=\"#E30083\" top_divider_height=\"70px\" bottom_divider_height=\"70px\" animation_direction=\"bottom\" use_background_color_gradient=\"on\" background_color_gradient_start=\"#FF147B\" background_color_gradient_end=\"#ffffff\" background_color_gradient_start_position=\"70%\" background_color_gradient_end_position=\"30%\"][et_pb_row column_structure=\"2_5,3_5\" _builder_version=\"3.25.4\" make_equal=\"on\"][et_pb_column type=\"2_5\" _builder_version=\"3.25.4\" custom_css_main_element=\"padding: 50px 40px 55px;||border-radius: 20px;||background: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0, 0, 0, 0.1), 0 13px 24px -11px rgba(0, 0, 0, 0);\"][et_pb_blurb title=\"Fasilitas\" use_icon=\"on\" font_icon=\"%%310%%\" use_icon_font_size=\"on\" icon_font_size=\"22px\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" header_font_size=\"18px\" header_letter_spacing=\"4px\" body_font=\"||||||||\" body_text_align=\"center\" background_color=\"#ffffff\" custom_css_blurb_image=\"margin-bottom: 20px;\"]<ol style=\"padding-bottom: 0;\">\n	<li>Masjid</li>\n	<li>Gedung Asrama</li>\n	<li>Gedung Sekolah</li>\n	<li>Lapangan Panahan</li>\n	<li>Kantin</li>\n	<li>UKP (Unit Kesehatan Pesantren)</li>\n</ol>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"3_5\" _builder_version=\"3.25.4\" custom_css_main_element=\"padding: 50px 40px 55px;||border-radius: 20px;||background: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0, 0, 0, 0.1), 0 13px 24px -11px rgba(0, 0, 0, 0);\"][et_pb_blurb title=\"Prestasi\" use_icon=\"on\" font_icon=\"%%310%%\" icon_color=\"#F86E01\" use_icon_font_size=\"on\" icon_font_size=\"22px\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" header_font_size=\"18px\" header_letter_spacing=\"4px\" body_font=\"||||||||\" body_text_align=\"center\" background_color=\"#ffffff\" custom_css_blurb_image=\"margin-bottom: 20px;\"]<div style=\"margin-bottom: 5px;\"><strong>Juara 2 Musabaqoh Hifzdil Qur\'an MAPSI SMP</strong><br /> <em>Dinas Pendidikan Kab. Sukoharjo Tahun 2016</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Juara 1 Musabaqoh Hifzdil Qur\'an MAPSI SMP</strong><br /> <em>Dinas Pendidikan Kab. Sukoharjo Tahun 2017</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Runner Up Musabaqoh Hifzdil Qur\'an Antar Pesantren</strong><br /> <em>Se-Indonesia Wilayah Jawa Tengah Tahun 2017</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Juara 2 Musabaqoh Hifzdil Qur\'an Milad MBS</strong><br /> <em>Tingkat Provinsi Yogyakarta Tahun 2018</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Juara 1 Olimpiade Hifzdil Qur\'an UAD Tingkat Nasional</strong><br /> <em>Purwokerto Tahun 2018</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Peraih Medali Emas dalam Kejuaraan Pencak Silat</strong><br /> <em>Yogyakarta Championship 4 Tingkat Nasional 2018</em></div>\n[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section]', 'Profil', '', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2019-07-10 03:52:51', '2019-07-10 03:52:51', '', 12, 'https://pondokroja.com/12-revision-v1/', 0, 'revision', '', 0),
(825, 1, '2019-07-10 03:57:15', '2019-07-10 03:57:15', '[et_pb_section fb_built=\"1\" fullwidth=\"on\" _builder_version=\"3.25.4\" background_color=\"#F86E01\" custom_padding=\"0px||0px\" bottom_divider_style=\"ramp2\" bottom_divider_color=\"#F7F9FB\" bottom_divider_height=\"148px\" bottom_divider_flip=\"horizontal\"][et_pb_fullwidth_header title=\"Profil Kami\" _builder_version=\"3.25.4\" title_font=\"||||||||\" title_font_size=\"40px\" background_color=\"#F86E01\" custom_padding=\"32px||29px|||\"][/et_pb_fullwidth_header][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"3.25.4\" use_background_color_gradient=\"on\" background_color_gradient_start=\"#F7F9FB\" background_color_gradient_end=\"#e1eafb\" background_image=\"https://pondokroja.com/wp-content/uploads/2019/07/Bg.png\" background_size=\"contain\" background_position=\"bottom_center\" custom_padding=\"||120px|||\" custom_padding_tablet=\"||90px\" custom_padding_phone=\"||80px|\"][et_pb_row custom_padding=\"0px|||||\" _builder_version=\"3.25.4\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\" text_font=\"||||||||\" text_text_align=\"center\" text_text_color=\"#ffffff\" header_font=\"|||on|||||\" header_text_align=\"center\" header_letter_spacing=\"4px\" header_3_font=\"|300||on|||||\" header_3_letter_spacing=\"4px\" custom_margin=\"||10px\"]<h3>Pondok Pesantren</h3>\n<h1>Rooihatul Jannah Hidayatullah</h1>[/et_pb_text][et_pb_text _builder_version=\"3.25.4\" custom_margin=\"||72px\"]<p style=\"text-align: justify;\">Pesantren Tahfidz Putri Rooihatul Jannah (Pondok Roja) adalah lembaga pendidikan islam setingkat SMP - SMA yang menerapkan kurikulum integral pendidikan Tauhid &amp; Pendidikan Nasional dengan lebih menguatkan menghafal Al Qur\'an sebagai program unggulan sehingga mencetak kader muslimah yang berakhlakul karimah dan berwawasan luas. Dengan didukung tenaga pengajar yang berkompeten lulusan dari pesantren dan perguruan tinggi.</p>[/et_pb_text][et_pb_blurb title=\"VISI\" module_class=\"blurb-full-width\" _builder_version=\"3.25.4\" custom_margin=\"||5px\" custom_css_blurb_title=\"background: #FF147B;||color: #FFFFFF;||font-weight: 300;||text-transform: uppercase;||letter-spacing: 4px;||margin-bottom: 0;||padding: 15px 40px 15px 40px;||border-top-left-radius: 20px;||border-bottom-right-radius: 20px;||position: absolute;||left: 40px;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);||top: -27.5px;\" custom_css_blurb_content=\"padding: 50px 40px 70px 40px;||border-radius: 20px 5px 20px 5px;||background-color: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);\"]Lembaga Pendidikan Islam Pencetak Kader Pemimpin Umat yang berakhlaq mulia, berwawasan luas, dan mampu mengembangkan diri untuk tegaknya peradapan Islam.[/et_pb_blurb][et_pb_blurb title=\"Misi\" module_class=\"blurb-full-width\" _builder_version=\"3.25.4\" custom_css_blurb_title=\"background: #FF147B;||color: #FFFFFF;||font-weight: 300;||text-transform: uppercase;||letter-spacing: 4px;||margin-bottom: 0;||padding: 15px 40px 15px 40px;||border-top-left-radius: 20px;||border-bottom-right-radius: 20px;||position: absolute;||left: 40px;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);||top: -27.5px;\" custom_css_blurb_content=\"padding: 60px 40px 40px 40px;||border-radius: 20px 5px 20px 5px;||background-color: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);\"]<table class=\"table-list\" style=\"margin-bottom: 0;\">\n<tbody>\n<tr>\n<td>1.</td>\n<td></td>\n<td>Membentuk generasi muslim yang unggul, berdikari, berpengetahuan luas siap menjadi da\'i dan ulama yang intelek.</td>\n<td></td>\n</tr>\n<tr>\n<td>2.</td>\n<td></td>\n<td>Membentuk karakter atau pribadi muslim yang bertauhid, beriman dan menjalankan syariah Allah.</td>\n<td></td>\n</tr>\n<tr>\n<td>3.</td>\n<td></td>\n<td>Menjadikan kampus pesantren Rooihatul Jannah sebagai lembaga berkualitas yang representatif, eksekutif &amp; kreatif serta menjadi rujukan ummat.</td>\n<td></td>\n</tr>\n</tbody>\n</table>[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" _builder_version=\"3.25.4\" background_color=\"rgba(255,255,255,0)\" custom_padding=\"0px||60px|||\"][et_pb_row custom_padding=\"0px||0px|||\" custom_margin=\"-20px||\" _builder_version=\"3.25.4\" custom_margin_tablet=\"0px||\" custom_margin_phone=\"10px|||\" custom_margin_last_edited=\"on|phone\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\" text_font=\"||||||||\" text_text_align=\"center\" header_font=\"||||||||\" header_5_font=\"|700||on|||||\" header_5_letter_spacing=\"4px\" custom_margin=\"||10px|\"]<h5>Sejarah Singkat Berdirinya</h5>[/et_pb_text][et_pb_text _builder_version=\"3.25.4\"]<p style=\"text-align: justify;\">Tepat bulan Juli tahun 2010, empat santri Hidayatullah Surakarta mendapat tugas dari Pimpinan Hidayatullah Surakarta untuk merintis di kota Sukoharjo atau terkenal dengan sebutan kota Makmur. Mereka bernama Sigit yang berasal dari Lampung, Syarif dari Magelang, Arifin dari Solo dan Syofyan dari Ternatai. Disebuah rumah dan tanah wakaf yang beralamat dibrumbung 03/02 dukuh sukoharjo dengan lauas tanah +- 1800 m2.</p>[/et_pb_text][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"1_5,1_5,1_5,1_5,1_5\" use_custom_gutter=\"on\" gutter_width=\"1\" custom_margin=\"50px||60px\" _builder_version=\"3.25.4\" width=\"90%\" width_last_edited=\"on|phone\" animation_direction=\"bottom\" custom_css_main_element=\"background-color: #ffffff;||border-radius: 15px 15px 15px 15px;||overflow: hidden;||border-top-width: 18px;||border-color: #3c39e6;||max-width: 1440px;||box-shadow: 0px 39px 80px -6px rgba(0,0,0,0.1);||padding: 60px 40px 10px;||border-bottom: 10px solid #7CDA24;\"][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Pembina\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Suparmana HS\nProf.dr.Dr. Harijono S.pKK[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Pengawas\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Ridho\nUst. Sulaiman Rodhi[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Ketua\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Ahmad Khamim\n-[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Sekretaris\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Surya Aditya Setyawan S.Pd.I[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Bendahara\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Sumardi\n-[/et_pb_blurb][/et_pb_column][/et_pb_row][et_pb_row custom_padding=\"0px||0px|||\" _builder_version=\"3.25.4\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\"]<p style=\"text-align: justify;\">Pondok Pesantren Rooihatul Jannah Hidayatullah Sukoharjo atau lebih dikenal dengan sebutan PONDOK ROJA adalah lembaga pendidikan Islam yang berciri khas dengan sistem pendidikan modern berjenjang 6 tahun plus 1 tahun pengabdian.</p>\n<p style=\"text-align: justify;\">Program utama adalah pendidikan guru penghafal al Qur’an/ Tarbiyatul Muhafidzotil Qur’an (TMQ). Secara realitas memang pondok pesantren ini di bawah naungan yayasan Hidayatullah Sukoharjo dan merupakan bagian dari Ormas besar Hidayatullah yang berpusat di Jakarta dengan kampus induk Pesantren Hidayatullah di Gunung Tembak, Balikpapan, Kalimantan Timur. Meski begitu dari sejak awal berdirinya, para pendiri pesantren (Father Founding) selalu mengingatkan dan mewaspadai akan adanya fantisme golongan tertentu, dengan berbagai cara sehingga siapa saja dan masyarakat secara umumpun bisa ikut bergabung dalam mengembangkan dan meningkatkan mutu dan kwalitas pendidikan yang ada dalam pesantren ini.</p>\n<p style=\"text-align: justify;\">Adapun untuk mewujudkan itu semua maka subtansi ajaran Islam yang menjadi basic sistem pendidikan dan pengajaran Islam di Pondok Roja senantisa bertumpu pada Al-Qur’an dan As-Sunnah yang sesuai dengan pemahaman Salafush Sholih secara Kaffah (universal), Syumul (Komperhenshif) dan Mutakaamil (integratif). Dengan cara pandang yang seperti inilah diharapkan para Pendiri Pondok ROJA Hidayatullah Sukoharjo ini bisa menjadi Generasi yang kritis dan taktis serta tidak mudah terjebak dalam sikap-sikap fanatisme golongan (sekte / madzhab) dan sikap taklid buta (mengikuti tanpa tahu dalilnya).</p>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" _builder_version=\"3.25.4\" background_color=\"#E30083\" custom_padding=\"||30px|||\" top_divider_height=\"70px\" bottom_divider_height=\"70px\" animation_direction=\"bottom\" use_background_color_gradient=\"on\" background_color_gradient_start=\"#FF147B\" background_color_gradient_end=\"#ffffff\" background_color_gradient_start_position=\"60%\" background_color_gradient_end_position=\"40%\"][et_pb_row column_structure=\"2_5,3_5\" _builder_version=\"3.25.4\" make_equal=\"on\"][et_pb_column type=\"2_5\" _builder_version=\"3.25.4\" custom_css_main_element=\"padding: 50px 40px 55px;||border-radius: 20px;||background: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0, 0, 0, 0.1), 0 13px 24px -11px rgba(0, 0, 0, 0);\"][et_pb_blurb title=\"Fasilitas\" use_icon=\"on\" font_icon=\"%%310%%\" use_icon_font_size=\"on\" icon_font_size=\"22px\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" header_font_size=\"18px\" header_letter_spacing=\"4px\" body_font=\"||||||||\" body_text_align=\"center\" background_color=\"#ffffff\" custom_css_blurb_image=\"margin-bottom: 20px;\"]Masjid\nGedung Asrama\nGedung Sekolah\nLapangan Panahan\nKantin\nUKP (Unit Kesehatan Pesantren)[/et_pb_blurb][/et_pb_column][et_pb_column type=\"3_5\" _builder_version=\"3.25.4\" custom_css_main_element=\"padding: 50px 40px 55px;||border-radius: 20px;||background: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0, 0, 0, 0.1), 0 13px 24px -11px rgba(0, 0, 0, 0);\"][et_pb_blurb title=\"Prestasi\" use_icon=\"on\" font_icon=\"%%310%%\" icon_color=\"#F86E01\" use_icon_font_size=\"on\" icon_font_size=\"22px\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" header_font_size=\"18px\" header_letter_spacing=\"4px\" body_font=\"||||||||\" body_text_align=\"center\" background_color=\"#ffffff\" custom_css_blurb_image=\"margin-bottom: 20px;\"]<div style=\"margin-bottom: 5px;\"><strong>Juara 2 Musabaqoh Hifzdil Qur\'an MAPSI SMP</strong><br /> <em>Dinas Pendidikan Kab. Sukoharjo Tahun 2016</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Juara 1 Musabaqoh Hifzdil Qur\'an MAPSI SMP</strong><br /> <em>Dinas Pendidikan Kab. Sukoharjo Tahun 2017</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Runner Up Musabaqoh Hifzdil Qur\'an Antar Pesantren</strong><br /> <em>Se-Indonesia Wilayah Jawa Tengah Tahun 2017</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Juara 2 Musabaqoh Hifzdil Qur\'an Milad MBS</strong><br /> <em>Tingkat Provinsi Yogyakarta Tahun 2018</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Juara 1 Olimpiade Hifzdil Qur\'an UAD Tingkat Nasional</strong><br /> <em>Purwokerto Tahun 2018</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Peraih Medali Emas dalam Kejuaraan Pencak Silat</strong><br /> <em>Yogyakarta Championship 4 Tingkat Nasional 2018</em></div>\n[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section]', 'Profil', '', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2019-07-10 03:57:15', '2019-07-10 03:57:15', '', 12, 'https://pondokroja.com/12-revision-v1/', 0, 'revision', '', 0),
(823, 1, '2019-07-10 03:55:56', '2019-07-10 03:55:56', '[et_pb_section fb_built=\"1\" fullwidth=\"on\" _builder_version=\"3.25.4\" background_color=\"#F86E01\" custom_padding=\"0px||0px\" bottom_divider_style=\"ramp2\" bottom_divider_color=\"#F7F9FB\" bottom_divider_height=\"148px\" bottom_divider_flip=\"horizontal\"][et_pb_fullwidth_header title=\"Profil Kami\" _builder_version=\"3.25.4\" title_font=\"||||||||\" title_font_size=\"40px\" background_color=\"#F86E01\" custom_padding=\"32px||29px|||\"][/et_pb_fullwidth_header][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"3.25.4\" use_background_color_gradient=\"on\" background_color_gradient_start=\"#F7F9FB\" background_color_gradient_end=\"#e1eafb\" background_image=\"https://pondokroja.com/wp-content/uploads/2019/07/Bg.png\" background_size=\"contain\" background_position=\"bottom_center\" custom_padding=\"||120px|||\" custom_padding_tablet=\"||90px\" custom_padding_phone=\"||80px|\"][et_pb_row custom_padding=\"0px|||||\" _builder_version=\"3.25.4\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\" text_font=\"||||||||\" text_text_align=\"center\" text_text_color=\"#ffffff\" header_font=\"|||on|||||\" header_text_align=\"center\" header_letter_spacing=\"4px\" header_3_font=\"|300||on|||||\" header_3_letter_spacing=\"4px\" custom_margin=\"||10px\"]<h3>Pondok Pesantren</h3>\n<h1>Rooihatul Jannah Hidayatullah</h1>[/et_pb_text][et_pb_text _builder_version=\"3.25.4\" custom_margin=\"||72px\"]<p style=\"text-align: justify;\">Pesantren Tahfidz Putri Rooihatul Jannah (Pondok Roja) adalah lembaga pendidikan islam setingkat SMP - SMA yang menerapkan kurikulum integral pendidikan Tauhid &amp; Pendidikan Nasional dengan lebih menguatkan menghafal Al Qur\'an sebagai program unggulan sehingga mencetak kader muslimah yang berakhlakul karimah dan berwawasan luas. Dengan didukung tenaga pengajar yang berkompeten lulusan dari pesantren dan perguruan tinggi.</p>[/et_pb_text][et_pb_blurb title=\"VISI\" module_class=\"blurb-full-width\" _builder_version=\"3.25.4\" custom_margin=\"||5px\" custom_css_blurb_title=\"background: #FF147B;||color: #FFFFFF;||font-weight: 300;||text-transform: uppercase;||letter-spacing: 4px;||margin-bottom: 0;||padding: 15px 40px 15px 40px;||border-top-left-radius: 20px;||border-bottom-right-radius: 20px;||position: absolute;||left: 40px;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);||top: -27.5px;\" custom_css_blurb_content=\"padding: 50px 40px 70px 40px;||border-radius: 20px 5px 20px 5px;||background-color: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);\"]Lembaga Pendidikan Islam Pencetak Kader Pemimpin Umat yang berakhlaq mulia, berwawasan luas, dan mampu mengembangkan diri untuk tegaknya peradapan Islam.[/et_pb_blurb][et_pb_blurb title=\"Misi\" module_class=\"blurb-full-width\" _builder_version=\"3.25.4\" custom_css_blurb_title=\"background: #FF147B;||color: #FFFFFF;||font-weight: 300;||text-transform: uppercase;||letter-spacing: 4px;||margin-bottom: 0;||padding: 15px 40px 15px 40px;||border-top-left-radius: 20px;||border-bottom-right-radius: 20px;||position: absolute;||left: 40px;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);||top: -27.5px;\" custom_css_blurb_content=\"padding: 60px 40px 40px 40px;||border-radius: 20px 5px 20px 5px;||background-color: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0,0,0,0.1), 0 13px 24px -11px rgba(0,0,0,0);\"]<table class=\"table-list\" style=\"margin-bottom: 0;\">\n<tbody>\n<tr>\n<td>1.</td>\n<td></td>\n<td>Membentuk generasi muslim yang unggul, berdikari, berpengetahuan luas siap menjadi da\'i dan ulama yang intelek.</td>\n<td></td>\n</tr>\n<tr>\n<td>2.</td>\n<td></td>\n<td>Membentuk karakter atau pribadi muslim yang bertauhid, beriman dan menjalankan syariah Allah.</td>\n<td></td>\n</tr>\n<tr>\n<td>3.</td>\n<td></td>\n<td>Menjadikan kampus pesantren Rooihatul Jannah sebagai lembaga berkualitas yang representatif, eksekutif &amp; kreatif serta menjadi rujukan ummat.</td>\n<td></td>\n</tr>\n</tbody>\n</table>[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" _builder_version=\"3.25.4\" background_color=\"rgba(255,255,255,0)\" custom_padding=\"0px||60px|||\"][et_pb_row custom_padding=\"0px||0px|||\" custom_margin=\"-20px||\" _builder_version=\"3.25.4\" custom_margin_tablet=\"0px||\" custom_margin_phone=\"10px|||\" custom_margin_last_edited=\"on|phone\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\" text_font=\"||||||||\" text_text_align=\"center\" header_font=\"||||||||\" header_5_font=\"|700||on|||||\" header_5_letter_spacing=\"4px\" custom_margin=\"||10px|\"]<h5>Sejarah Singkat Berdirinya</h5>[/et_pb_text][et_pb_text _builder_version=\"3.25.4\"]<p style=\"text-align: justify;\">Tepat bulan Juli tahun 2010, empat santri Hidayatullah Surakarta mendapat tugas dari Pimpinan Hidayatullah Surakarta untuk merintis di kota Sukoharjo atau terkenal dengan sebutan kota Makmur. Mereka bernama Sigit yang berasal dari Lampung, Syarif dari Magelang, Arifin dari Solo dan Syofyan dari Ternatai. Disebuah rumah dan tanah wakaf yang beralamat dibrumbung 03/02 dukuh sukoharjo dengan lauas tanah +- 1800 m2.</p>[/et_pb_text][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"1_5,1_5,1_5,1_5,1_5\" use_custom_gutter=\"on\" gutter_width=\"1\" custom_margin=\"50px||60px\" _builder_version=\"3.25.4\" width=\"90%\" width_last_edited=\"on|phone\" animation_direction=\"bottom\" custom_css_main_element=\"background-color: #ffffff;||border-radius: 15px 15px 15px 15px;||overflow: hidden;||border-top-width: 18px;||border-color: #3c39e6;||max-width: 1440px;||box-shadow: 0px 39px 80px -6px rgba(0,0,0,0.1);||padding: 60px 40px 10px;||border-bottom: 10px solid #7CDA24;\"][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Pembina\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Suparmana HS\nProf.dr.Dr. Harijono S.pKK[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Pengawas\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Ridho\nUst. Sulaiman Rodhi[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Ketua\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Ahmad Khamim\n-[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Sekretaris\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Surya Aditya Setyawan S.Pd.I[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_5\" _builder_version=\"3.25.4\"][et_pb_blurb title=\"Bendahara\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" body_font=\"||||||||\" body_text_align=\"center\" custom_margin=\"||40px\" custom_css_blurb_title=\"font-weight: 600;||letter-spacing: 4px;\"]Ust. Sumardi\n-[/et_pb_blurb][/et_pb_column][/et_pb_row][et_pb_row custom_padding=\"0px||0px|||\" _builder_version=\"3.25.4\"][et_pb_column type=\"4_4\" _builder_version=\"3.25.4\"][et_pb_text _builder_version=\"3.25.4\"]<p style=\"text-align: justify;\">Pondok Pesantren Rooihatul Jannah Hidayatullah Sukoharjo atau lebih dikenal dengan sebutan PONDOK ROJA adalah lembaga pendidikan Islam yang berciri khas dengan sistem pendidikan modern berjenjang 6 tahun plus 1 tahun pengabdian.</p>\n<p style=\"text-align: justify;\">Program utama adalah pendidikan guru penghafal al Qur’an/ Tarbiyatul Muhafidzotil Qur’an (TMQ). Secara realitas memang pondok pesantren ini di bawah naungan yayasan Hidayatullah Sukoharjo dan merupakan bagian dari Ormas besar Hidayatullah yang berpusat di Jakarta dengan kampus induk Pesantren Hidayatullah di Gunung Tembak, Balikpapan, Kalimantan Timur. Meski begitu dari sejak awal berdirinya, para pendiri pesantren (Father Founding) selalu mengingatkan dan mewaspadai akan adanya fantisme golongan tertentu, dengan berbagai cara sehingga siapa saja dan masyarakat secara umumpun bisa ikut bergabung dalam mengembangkan dan meningkatkan mutu dan kwalitas pendidikan yang ada dalam pesantren ini.</p>\n<p style=\"text-align: justify;\">Adapun untuk mewujudkan itu semua maka subtansi ajaran Islam yang menjadi basic sistem pendidikan dan pengajaran Islam di Pondok Roja senantisa bertumpu pada Al-Qur’an dan As-Sunnah yang sesuai dengan pemahaman Salafush Sholih secara Kaffah (universal), Syumul (Komperhenshif) dan Mutakaamil (integratif). Dengan cara pandang yang seperti inilah diharapkan para Pendiri Pondok ROJA Hidayatullah Sukoharjo ini bisa menjadi Generasi yang kritis dan taktis serta tidak mudah terjebak dalam sikap-sikap fanatisme golongan (sekte / madzhab) dan sikap taklid buta (mengikuti tanpa tahu dalilnya).</p>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" _builder_version=\"3.25.4\" background_color=\"#E30083\" custom_padding=\"||30px|||\" top_divider_height=\"70px\" bottom_divider_height=\"70px\" animation_direction=\"bottom\" use_background_color_gradient=\"on\" background_color_gradient_start=\"#FF147B\" background_color_gradient_end=\"#ffffff\" background_color_gradient_start_position=\"60%\" background_color_gradient_end_position=\"40%\"][et_pb_row column_structure=\"2_5,3_5\" _builder_version=\"3.25.4\" make_equal=\"on\"][et_pb_column type=\"2_5\" _builder_version=\"3.25.4\" custom_css_main_element=\"padding: 50px 40px 55px;||border-radius: 20px;||background: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0, 0, 0, 0.1), 0 13px 24px -11px rgba(0, 0, 0, 0);\"][et_pb_blurb title=\"Fasilitas\" use_icon=\"on\" font_icon=\"%%310%%\" use_icon_font_size=\"on\" icon_font_size=\"22px\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" header_font_size=\"18px\" header_letter_spacing=\"4px\" body_font=\"||||||||\" body_text_align=\"center\" background_color=\"#ffffff\" custom_css_blurb_image=\"margin-bottom: 20px;\"]<ol style=\"padding-bottom: 0;\">\n	<li>Masjid</li>\n	<li>Gedung Asrama</li>\n	<li>Gedung Sekolah</li>\n	<li>Lapangan Panahan</li>\n	<li>Kantin</li>\n	<li>UKP (Unit Kesehatan Pesantren)</li>\n</ol>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"3_5\" _builder_version=\"3.25.4\" custom_css_main_element=\"padding: 50px 40px 55px;||border-radius: 20px;||background: #FFFFFF;||box-shadow: 0 5px 20px 0 rgba(0, 0, 0, 0.1), 0 13px 24px -11px rgba(0, 0, 0, 0);\"][et_pb_blurb title=\"Prestasi\" use_icon=\"on\" font_icon=\"%%310%%\" icon_color=\"#F86E01\" use_icon_font_size=\"on\" icon_font_size=\"22px\" _builder_version=\"3.25.4\" header_font=\"|||on|||||\" header_text_align=\"center\" header_font_size=\"18px\" header_letter_spacing=\"4px\" body_font=\"||||||||\" body_text_align=\"center\" background_color=\"#ffffff\" custom_css_blurb_image=\"margin-bottom: 20px;\"]<div style=\"margin-bottom: 5px;\"><strong>Juara 2 Musabaqoh Hifzdil Qur\'an MAPSI SMP</strong><br /> <em>Dinas Pendidikan Kab. Sukoharjo Tahun 2016</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Juara 1 Musabaqoh Hifzdil Qur\'an MAPSI SMP</strong><br /> <em>Dinas Pendidikan Kab. Sukoharjo Tahun 2017</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Runner Up Musabaqoh Hifzdil Qur\'an Antar Pesantren</strong><br /> <em>Se-Indonesia Wilayah Jawa Tengah Tahun 2017</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Juara 2 Musabaqoh Hifzdil Qur\'an Milad MBS</strong><br /> <em>Tingkat Provinsi Yogyakarta Tahun 2018</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Juara 1 Olimpiade Hifzdil Qur\'an UAD Tingkat Nasional</strong><br /> <em>Purwokerto Tahun 2018</em></div>\n<div style=\"margin-bottom: 5px;\"><strong>Peraih Medali Emas dalam Kejuaraan Pencak Silat</strong><br /> <em>Yogyakarta Championship 4 Tingkat Nasional 2018</em></div>\n[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section]', 'Profil', '', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2019-07-10 03:55:56', '2019-07-10 03:55:56', '', 12, 'https://pondokroja.com/12-revision-v1/', 0, 'revision', '', 0);
