(898, 1, '2019-07-11 09:57:51', '2019-07-11 09:57:51', '#top-menu li a {\r\n	font-weight: 600;\r\n    color: rgba(32,41,47,.6);\r\n}\r\nbody {\r\n	font-weight: 400;\r\n	letter-spacing: .5px;\r\n}\r\n#logo {\r\n	max-height: 100%;\r\n}\r\n#et-info {\r\n	width: 100%;\r\n	padding-top: 1px;\r\n}\r\n#top-header .et-social-icons {\r\n	float: right;\r\n}\r\n#top-header .et-social-icon a {\r\n	margin-top: 3px;\r\n}\r\n#top-header .et-social-google-plus {\r\n	display: none;\r\n}\r\n@media (min-width: 981px) {\r\n	#main-header.et-fixed-header {\r\n		-webkit-box-sizing: border-box;\r\n		-moz-box-sizing: border-box;\r\n		-webkit-box-shadow: 0 5px 10px rgba(7,51,84,0.10);\r\n		-moz-box-shadow: 0 5px 10px rgba(7,51,84,0.10);\r\n		box-shadow: 0 5px 10px rgba(7,51,84,0.10) !important;\r\n	}\r\n}\r\n#main-header {\r\n	-webkit-box-sizing: border-box;\r\n    -moz-box-sizing: border-box;\r\n    -webkit-box-shadow: 0 5px 10px rgba(7,51,84,0.10);\r\n    -moz-box-shadow: 0 5px 10px rgba(7,51,84,0.10);\r\n    box-shadow: 0 5px 10px rgba(7,51,84,0.10);\r\n	z-index: 100001;\r\n}\r\n#et-info #et-info-email:before {\r\n	display: none;\r\n}\r\n#et-info #et-info-phone {\r\n	margin-right: 20px;\r\n}\r\n.et-fixed-header #logo {\r\n	max-height: 77%;\r\n}\r\n#footer-bottom .et-social-icon {\r\n	margin-left: 5px;\r\n}\r\n#footer-bottom .et-social-icon a {\r\n	font-size: 14px;\r\n    width: 35px;\r\n    height: 35px;\r\n    line-height: 35px;\r\n    border-width: 1px !important;\r\n    border-style: solid !important;\r\n    border-color: #F86E01;\r\n	background-color: #F86E01;\r\n	color: #FFFFFF;\r\n    border-radius: 4px;\r\n    transition: all 0.2s ease-in-out 0s;\r\n}\r\n#footer-bottom .et-social-icon.et-social-google-plus {\r\n	display: none;\r\n}\r\n#footer-widgets {\r\n	border-bottom: 1px solid #DDD;\r\n}\r\n#footer-bottom {\r\n	padding: 22px 0 16px;\r\n}\r\n#footer-info a {\r\n	color: #7cda24!important;\r\n	font-weight: normal;\r\n}\r\n.footer-widget strong {\r\n	font-weight: 600;\r\n}\r\n#footer-widgets .footer-widget li:before {\r\n	display: none;\r\n}\r\n#footer-widgets .footer-widget li {\r\n	padding-left: 0;\r\n	width: 100%;\r\n    border-bottom: 1px solid #EEEEEE;\r\n	padding-bottom: 8px;\r\n}\r\n#footer-widgets .footer-widget li:last-child {\r\n	border-bottom: none;\r\n}\r\n.footer-widget .widget_nav_menu {\r\n	width: 100%;\r\n}\r\n.footer-widget .widget_recent_entries li a,\r\n.footer-widget .widget_nav_menu li a {\r\n	color: inherit !important;\r\n}\r\n.footer-widget .widget_recent_entries li a:hover,\r\n.footer-widget .widget_nav_menu li a:hover {\r\n	color: #FF147B!important;\r\n}\r\n@media (min-width: 981px) {\r\n	.et_pb_gutters3 .footer-widget {\r\n		margin-bottom: 4%;\r\n	}\r\n}\r\n#sidebar h4.widgettitle,\r\n.et_pb_widget_area h4.widgettitle {\r\n	text-transform: uppercase;\r\n    letter-spacing: 2px;\r\n    font-weight: 600;\r\n}\r\n#main-footer .footer-widget h4 {\r\n    text-transform: uppercase;\r\n    letter-spacing: 2px;\r\n    font-weight: 600;\r\n    font-size: 14px;\r\n    margin-bottom: 12px;\r\n}\r\n.single.single-post h1.entry-title {\r\n	font-weight: 600;\r\n    letter-spacing: 2px;\r\n    text-transform: uppercase;\r\n    font-size: 22px;\r\n    line-height: 35px;\r\n}\r\n#top-menu li.nav-donation {\r\n	background: #7cda24;\r\n	margin-top: -10px;\r\n	padding: 10px 12px !important;\r\n	transition: all 0.2s ease-in-out 0s;\r\n	border-radius: 4px;\r\n}\r\n#top-menu li.nav-donation:hover {\r\n	background: #FF147B;\r\n	transition: all 0.2s ease-in-out 0s;\r\n}\r\n#top-menu li.nav-donation a {\r\n	color: #FFFFFF !important;\r\n	margin-bottom: 0;\r\n    padding-bottom: 0 !important;\r\n}\r\n#top-menu li.nav-donation:hover,\r\n#top-menu li.nav-donation a:hover {\r\n	color: #FFFFFF !important;\r\n	opacity: 1;\r\n}\r\n@media (max-width: 981px) {\r\n	.et_mobile_menu li.nav-donation a {\r\n		color: #7CDA24;\r\n		font-weight: 800;\r\n	}\r\n}\r\n@media (min-width: 981px) {\r\n	.et_right_sidebar #sidebar {\r\n		padding-left: 0;\r\n	}\r\n}\r\n@media (min-width: 981px) {\r\n	#main-content .container:before {\r\n		display: none;\r\n	}\r\n}\r\nbody.page #page-container .et_pb_contact_form_0.et_pb_contact_form_container.et_pb_module .et_pb_button,\r\nbody.page #page-container .et_pb_contact_form_0.et_pb_contact_form_container.et_pb_module .et_pb_button:hover {\r\n	padding: 0.4em 1em 0.2em!important;\r\n}\r\n.et_pb_widget ul li {\r\n	border-bottom: 1px solid #EEEEEE;\r\n    padding-bottom: 10px;\r\n    margin-bottom: 11px;\r\n}\r\n.et_pb_widget ul li:last-child {\r\n	border-bottom: none;\r\n}\r\n#commentform input[type=email], #commentform input[type=text], #commentform input[type=url], #commentform textarea {\r\n	border-radius: 4px 4px 4px 4px;\r\n    border-width: 1px;\r\n    border-color: #DDDDDD;\r\n	background: #F9FAFD;\r\n}\r\n.form-submit .et_pb_button {\r\n    background: #7CDA24;\r\n    color: #FFFFFF !important;\r\n    border-radius: 4px;\r\n    border: none;\r\n}\r\n.form-submit .et_pb_button:hover {\r\n	background: #FF147B;\r\n}\r\n.custom-main-slider .et_pb_slide_description {\r\n	padding-top: 12.5%;\r\n	padding-bottom: 11.5%;\r\n	padding-right: 2%;\r\n	padding-left: 2%;\r\n}\r\n@media only screen and (max-width: 767px) {\r\n	.custom-main-slider .et_pb_slide_description {\r\n		padding-top: 14.5%;\r\n		padding-bottom: 22.5%;\r\n	}\r\n}\r\n.custom-main-slider.et_pb_fullwidth_section .et_pb_slider .et_pb_slide .et_pb_slide_description .et_pb_slide_title {\r\n    font-weight: 100!important;\r\n}\r\n.flex-display {\r\n	display: flex;\r\n}\r\n.flex-display .et_pb_column {\r\n	margin: auto;\r\n}\r\n.table-list {\r\n	border: none !important;\r\n	padding: 0;\r\n	margin: 0;\r\n}\r\n.table-list tr td {\r\n	border: none;\r\n	padding: 0;\r\n	vertical-align: top;\r\n}\r\n.table-list tr td:first-child {\r\n	width: 20px;\r\n}\r\n.custom-blog-grid article {\r\n	border: none !important;\r\n	padding: 0 !important;\r\n}\r\n.custom-blog-grid .et_pb_image_container {\r\n	padding: 0;\r\n	margin: 0 0 10px !important;\r\